"""Native, disposable diagnostic records and visible labels for street edits.

Records are generated output, never mixed into the editable Section polylines.
Codes are stable machine-readable identifiers; human text is kept in one table.
Diagnostic meshes are explicitly marked so geometry checks can exclude them.
"""

REASONS = {
    1: 'invalid source data',
    2: 'junction trim / mouth conflict',
    3: 'bend / curvature limit',
    4: 'sampling budget exceeded',
    5: 'folded carriageway quads',
    6: 'boundary overlap or budget',
    7: 'paired carriageway / separator conflict',
    8: 'incompatible Section seam',
    9: 'source topology changed; rebuild required',
    20: 'invalid intersection geometry',
    30: 'source binding or global controls',
    31: 'network sampling budget exceeded',
    32: 'network assembly or ownership rejected',
    33: 'internal separator rejected; pavement retained',
    40: 'Bundle centerlines cross or touch',
    41: 'Bundle centerline separation unresolved',
    50: 'Bundle cross-section correspondence invalid',
    51: 'folded Bundle surface quads',
    52: 'Bundle boundary overlap or budget',
    53: 'Bundle mesh sampling budget exceeded',
    54: 'Bundle band seam geometry disagrees',
    60: 'Bundle axial mapping invalid',
    61: 'Bundle boundary approximation unresolved',
    62: 'Oblique Bundle cuts require compatible straight leads and matching attached or clipped ends',
    63: 'Bundle free-cap profile or exact body seam is incompatible',
    64: 'Incompatible Sections in a continuous Bundle member',
    65: 'Insufficient clear length for the declared width transition',
}


def record(g, position, code, section_id=-1, bundle_id=-1, intersection_id=-1):
    """Create one POINTCLOUD record at an affected source location."""
    node = g.node('GeometryNodePoints', 'Generated diagnostic record; never editable input')
    node.inputs['Count'].default_value = 1
    node.inputs['Radius'].default_value = .1
    g.set(position, node.inputs['Position'])
    geometry = node.outputs['Points']
    for name, value in [('st_diagnostic_code', code), ('st_section_id', section_id),
                        ('st_bundle_id', bundle_id), ('st_intersection_id', intersection_id)]:
        geometry = g.store(geometry, name, value, 'INT')
    return geometry


def point(g, reject, code, section_id, bundle_id, position, intersection_id=-1):
    """Create a record only for a rejected component (network-builder API)."""
    geometry = record(g, position, code, section_id, bundle_id, intersection_id)
    return g.switch(reject, None, geometry, 'GEOMETRY', 'Only rejected components need a warning')


def _integer_text(g, value):
    # Blender 5.2 supports integer conversion directly. The default FLOAT mode
    # would round large durable IDs before displaying them.
    text = g.node('FunctionNodeValueToString', 'Exact diagnostic ID')
    text.data_type = 'INT'
    g.set(value, text.inputs['Value'])
    return text.outputs['String']


def render(g, points, material=None):
    """Render a red-warning marker and an ID/reason label natively in GN.

    The caller supplies the warning material (usually red). Geometry lies in XY,
    slightly above its input location, so a top view explains an invalid edit
    without Python handlers, timers, polling, or opening a panel.
    """
    size = g.node('GeometryNodeAttributeDomainSize', 'Rejected component count')
    size.component = 'POINTCLOUD'
    g.set(points, size.inputs['Geometry'])
    ri = g.node('GeometryNodeRepeatInput', 'Annotate each rejected component')
    ro = g.node('GeometryNodeRepeatOutput', 'Visible diagnostics only')
    ro.repeat_items.clear()
    ro.repeat_items.new('GEOMETRY', 'Markers')
    ri.pair_with_output(ro)
    g.set(size.outputs['Point Count'], ri.inputs['Iterations'])
    index = ri.outputs['Iteration']
    pos = g.node('GeometryNodeInputPosition', 'Diagnostic point position').outputs[0]

    def sample(name, kind='INT'):
        return g.sample(points, g.named(name, kind), index, kind)

    code, sid = sample('st_diagnostic_code'), sample('st_section_id')
    jid, bundle = sample('st_intersection_id'), sample('st_bundle_id')
    reason = 'unresolved geometry'
    for number, text in REASONS.items():
        reason = g.switch(g.compare(code, number, kind='INT'), reason, text, 'STRING')
    is_section = g.compare(sid, 0, 'GREATER_EQUAL', 'INT')
    number = _integer_text(g, g.switch(is_section, jid, sid, 'INT'))
    prefix = g.switch(is_section, 'Intersection ', 'Section ', 'STRING')
    is_bundle = g.all(g.boolean('NOT', is_section), g.compare(jid, 0, 'LESS_THAN', 'INT'),
                      g.compare(bundle, 0, 'GREATER_EQUAL', 'INT'))
    number = g.switch(is_bundle, number, _integer_text(g, bundle), 'STRING')
    prefix = g.switch(is_bundle, prefix, 'Bundle ', 'STRING')
    is_region = g.compare(sample('st_cn_kind'), 7, kind='INT')
    number = g.switch(is_region, number, _integer_text(g, sample('st_cn_owner')), 'STRING')
    prefix = g.switch(is_region, prefix, 'Separator region ', 'STRING')
    text = g.node('GeometryNodeStringJoin', 'Explain the missing component')
    # Multi-input sockets only retain links; constant pieces need real outputs.
    separator = g.node('FunctionNodeInputString', 'Diagnostic label separator')
    separator.string = ': '
    for piece in (reason, separator.outputs['String'], number, prefix):
        g.set(piece, text.inputs['Strings'])
    network_prefix=g.node('FunctionNodeInputString','Network diagnostic prefix')
    network_prefix.string='Network: '
    network_message=g.node('GeometryNodeStringJoin','Explain a failure without a trusted local owner')
    for piece in (reason,network_prefix.outputs['String']):g.set(piece,network_message.inputs['Strings'])
    no_owner=g.all(g.boolean('NOT',is_region),g.compare(sid,0,'LESS_THAN','INT'),g.compare(jid,0,'LESS_THAN','INT'),
                   g.compare(bundle,0,'LESS_THAN','INT'))
    message=g.switch(no_owner,text.outputs['String'],network_message.outputs['String'],'STRING')
    network_text = g.switch(g.compare(code, 30, kind='INT'), message,
                            'Network: source binding or global controls', 'STRING')
    network_text = g.switch(g.compare(code, 31, kind='INT'), network_text,
                            'Network: sampling budget exceeded', 'STRING')
    curves = g.node('GeometryNodeStringToCurves', 'Native live edit warning text')
    g.set(network_text, curves.inputs['String'])
    curves.inputs['Size'].default_value = .42
    realize = g.node('GeometryNodeRealizeInstances', 'Realize diagnostic glyphs')
    g.set(curves.outputs['Curve Instances'], realize.inputs['Geometry'])
    fill = g.node('GeometryNodeFillCurve', 'Fill diagnostic glyphs; not road topology')
    g.set(realize.outputs['Geometry'], fill.inputs['Curve'])
    label_offset = g.node('GeometryNodeTransform', 'Place warning beside the rejected Section')
    g.set(fill.outputs['Mesh'], label_offset.inputs['Geometry'])
    # Multiple members may correctly report one contact position. Stack their
    # labels while retaining the true position of each diagnostic ring.
    g.set(g.xyz(.8, g.math('ADD', .2, g.math('MULTIPLY', .65, index)), .02),
          label_offset.inputs['Translation'])

    ring = g.node('GeometryNodeCurvePrimitiveCircle', 'Diagnostic ring')
    ring.inputs['Resolution'].default_value = 24
    ring.inputs['Radius'].default_value = .5
    profile = g.node('GeometryNodeCurvePrimitiveCircle', 'Diagnostic ring thickness')
    profile.inputs['Resolution'].default_value = 4
    profile.inputs['Radius'].default_value = .045
    tube = g.node('GeometryNodeCurveToMesh', 'Visible warning ring')
    g.set(ring.outputs['Curve'], tube.inputs['Curve'])
    g.set(profile.outputs['Curve'], tube.inputs['Profile Curve'])
    join = g.node('GeometryNodeJoinGeometry', 'Warning ring and explanation')
    g.set(tube.outputs['Mesh'], join.inputs['Geometry'])
    g.set(label_offset.outputs['Geometry'], join.inputs['Geometry'])
    move = g.node('GeometryNodeTransform', 'Place diagnostics at affected input location')
    g.set(join.outputs['Geometry'], move.inputs['Geometry'])
    position = g.sample(points, pos, index, 'FLOAT_VECTOR')
    g.set(g.vector('ADD', position, (0., 0., .35)), move.inputs['Translation'])
    geometry = move.outputs['Geometry']
    geometry = g.store(geometry, 'st_diagnostic', True, 'BOOLEAN', 'FACE')
    for name, value in [('st_diagnostic_code', code), ('st_section_id', sid),
                        ('st_bundle_id', bundle), ('st_intersection_id', jid)]:
        geometry = g.store(geometry, name, value, 'INT', 'FACE')
    if material is not None:
        mat = g.node('GeometryNodeSetMaterial', 'Warning material')
        g.set(geometry, mat.inputs['Geometry'])
        g.set(material, mat.inputs['Material'])
        geometry = mat.outputs['Geometry']
    append = g.node('GeometryNodeJoinGeometry', 'Append one diagnostic marker')
    g.set(ri.outputs['Markers'], append.inputs['Geometry'])
    g.set(geometry, append.inputs['Geometry'])
    g.set(append.outputs['Geometry'], ro.inputs['Markers'])
    return ro.outputs['Markers']
